import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.D7EuCHIT.js";const _=JSON.parse('{"title":"Host 与绘制提交参考","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/host.md","filePath":"plugins/host.md","lastUpdated":1791751912000}'),a={name:"plugins/host.md"};function c(s,t,i,n,p,l){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="host-与绘制提交参考" tabindex="-1">Host 与绘制提交参考 <a class="header-anchor" href="#host-与绘制提交参考" aria-label="Permalink to &quot;Host 与绘制提交参考&quot;">​</a></h1><p>Host 是公开上下文，不是宿主实现对象。先检查 size/abi，再使用字段；不要把 user 强转为私有类。所有函数都使用其明确的 user 参数。</p><table tabindex="0"><thead><tr><th>字段/回调</th><th>含义</th></tr></thead><tbody><tr><td><code>log</code></td><td>诊断文本；不输出用户歌词与秘密</td></tr><tr><td><code>request_frame</code></td><td>请求下一帧，动画或异步结果完成后调用</td></tr><tr><td><code>now_ns</code></td><td>单调纳秒，不是音乐进度</td></tr><tr><td><code>density</code></td><td>dp 到像素密度；不是完整字体缩放策略</td></tr><tr><td><code>submit</code></td><td>提交 Scene，命令/文本被复制，image 像素借用至帧结束</td></tr><tr><td><code>layer</code></td><td>声明服务命中层及 z、几何区域</td></tr><tr><td><code>library_query</code> / <code>search_query</code></td><td>旧有界 LyraRecord 查询；完整信息优先 catalog</td></tr><tr><td><code>config_text</code></td><td>读已声明配置表，非完整 UI 状态对象</td></tr><tr><td><code>request_permission</code></td><td>请求宿主已声明的权限</td></tr><tr><td><code>transport</code></td><td>兼容播放操作；新代码优先 playback 接口</td></tr><tr><td><code>find</code></td><td>查 capability 当前实现，依所属服务 lifetime 使用</td></tr><tr><td><code>set_panes</code></td><td>根/导航实现发布面板几何</td></tr><tr><td><code>acquire_surface</code></td><td>平台表面能力；返回值依平台，不是通用 GLES 句柄</td></tr><tr><td><code>section</code></td><td>当前可查询区域的几何；未知能力失败</td></tr><tr><td><code>listen</code></td><td>接收区域/事件回调，遵守服务卸载寿命</td></tr><tr><td><code>java_vm</code> / <code>android_context</code></td><td>Android 扩展；其他平台可能为空</td></tr><tr><td><code>query_interface</code></td><td>查询版本与结构大小匹配的能力</td></tr></tbody></table><p>权限状态：GRANTED=0、DENIED=1、UNDECLARED=2、UNAVAILABLE=3。未在宿主 Android 清单声明的权限不能靠运行时请求获得。</p><h2 id="旧-transport-的单位" tabindex="-1">旧 transport 的单位 <a class="header-anchor" href="#旧-transport-的单位" aria-label="Permalink to &quot;旧 transport 的单位&quot;">​</a></h2><p>0 toggle；1 seek(ms)；2 position(ms)；3 设置 mode；4 读取 mode；5 队列数；6 查询队列行对应目录索引（ms 参数承载 row）；7 播放队列行；8 当前队列行。这个 ms 参数在所有 action 下不是同一种意义，建议新代码用 typed playback command/queue，避免单位误用。</p><h2 id="scene-与命中" tabindex="-1">Scene 与命中 <a class="header-anchor" href="#scene-与命中" aria-label="Permalink to &quot;Scene 与命中&quot;">​</a></h2><p>所有 count 对应真实数组容量，size 设为 sizeof。基本形状/glyph 几何为像素，ripple 中心为归一化卡片坐标。不要提交悬空 text、无效 image 尺寸或伪造 cover key。</p><p>基础文字与扩展文字层不是同一结构，检查 Scene size 覆盖尾部再使用 text_layers/shape_layers。当前默认实现每次最多 4096 个扩展层，插件应在可见区域内生成命令并复用缓冲。自定义输入使用 LyraInput DOWN=0、UP=1、MOVE=2、CANCEL=3；取消不应当作点击确认。</p><p>根替换负责发布自己的布局并接管输入。局部替换只负责自己被路由的区域；不要绘制默认结果之后再遮盖当作真正替换。</p><p><a href="/LyraPlayer-docs-site/reference/abi">完整 SDK 声明</a> · <a href="/LyraPlayer-docs-site/plugins/interfaces">接口查询</a> · <a href="/LyraPlayer-docs-site/plugins/lifecycle">生命周期</a></p>',11)])])}const u=e(a,[["render",c]]);export{_ as __pageData,u as default};
